package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"regexp"
	"strings"
	"sync"
	"time"
)

// Job represents a background processing task
type Job struct {
	ID        string `json:"id"`
	Payload   string `json:"payload"`
	Pattern   string `json:"pattern"`
	Priority  int    `json:"priority"`
	CreatedAt time.Time
}

// JobResult holds the outcome of processing
type JobResult struct {
	JobID   string `json:"job_id"`
	Matches int    `json:"matches"`
	Status  string `json:"status"`
}

// PatternRegistry caches compiled patterns for reuse
type PatternRegistry struct {
	mu       sync.RWMutex
	patterns map[string]*regexp.Regexp
}

func NewPatternRegistry() *PatternRegistry {
	return &PatternRegistry{
		patterns: make(map[string]*regexp.Regexp),
	}
}

// GetOrCompile retrieves a cached pattern or compiles and caches it
func (pr *PatternRegistry) GetOrCompile(pattern string) (*regexp.Regexp, error) {
	pr.mu.RLock()
	if re, ok := pr.patterns[pattern]; ok {
		pr.mu.RUnlock()
		return re, nil
	}
	pr.mu.RUnlock()

	pr.mu.Lock()
	defer pr.mu.Unlock()

	// Double-check after acquiring write lock
	if re, ok := pr.patterns[pattern]; ok {
		return re, nil
	}

	re, err := regexp.Compile(pattern)
	if err != nil {
		return nil, fmt.Errorf("invalid pattern: %w", err)
	}
	pr.patterns[pattern] = re
	return re, nil
}

// WorkerPool manages background job processing
type WorkerPool struct {
	jobs     chan Job
	results  chan JobResult
	registry *PatternRegistry
	wg       sync.WaitGroup
}

func NewWorkerPool(size int, registry *PatternRegistry) *WorkerPool {
	wp := &WorkerPool{
		jobs:     make(chan Job, 100),
		results:  make(chan JobResult, 100),
		registry: registry,
	}
	for i := 0; i < size; i++ {
		wp.wg.Add(1)
		go wp.worker(i)
	}
	return wp
}

func (wp *WorkerPool) worker(id int) {
	defer wp.wg.Done()
	for job := range wp.jobs {
		result := wp.processJob(job)
		wp.results <- result
	}
}

// processJob applies the pattern against the payload
func (wp *WorkerPool) processJob(job Job) JobResult {
	re, err := wp.registry.GetOrCompile(job.Pattern)
	if err != nil {
		return JobResult{JobID: job.ID, Status: "error: " + err.Error()}
	}

	// Split payload into lines and match each
	lines := strings.Split(job.Payload, "\n")
	matches := 0
	for _, line := range lines {
		if re.MatchString(line) {
			matches++
		}
	}

	return JobResult{JobID: job.ID, Matches: matches, Status: "completed"}
}

// sanitizePattern ensures the pattern is safe for compilation
// Go's regexp package uses RE2 which is linear-time, but we add
// additional validation for defense in depth
func sanitizePattern(pattern string) (string, error) {
	if len(pattern) > 256 {
		return "", fmt.Errorf("pattern too long")
	}
	// Disallow backreferences and lookaheads (not supported in RE2 anyway)
	dangerous := []string{"(?<=", "(?<!", "(?=", "(?!"}
	for _, d := range dangerous {
		if strings.Contains(pattern, d) {
			return "", fmt.Errorf("unsupported pattern construct: %s", d)
		}
	}
	return pattern, nil
}

// ReverseProxyHandler simulates the entry point behind nginx/haproxy
// The proxy sets X-Request-Timeout header based on client tier
func makeJobHandler(wp *WorkerPool) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		var job Job
		if err := json.NewDecoder(r.Body).Decode(&job); err != nil {
			http.Error(w, "invalid request body", http.StatusBadRequest)
			return
		}

		// Validate and sanitize the pattern
		sanitized, err := sanitizePattern(job.Pattern)
		if err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		job.Pattern = sanitized

		// Parse timeout from reverse proxy header (default 30s)
		timeoutStr := r.Header.Get("X-Request-Timeout")
		timeout := 30 * time.Second
		if timeoutStr != "" {
			if d, err := time.ParseDuration(timeoutStr); err == nil && d > 0 {
				timeout = d
			}
		}

		ctx, cancel := context.WithTimeout(r.Context(), timeout)
		defer cancel()

		job.CreatedAt = time.Now()
		job.ID = fmt.Sprintf("job-%d", time.Now().UnixNano())

		// Submit job
		select {
		case wp.jobs <- job:
		case <-ctx.Done():
			http.Error(w, "queue full", http.StatusServiceUnavailable)
			return
		}

		// Wait for result
		select {
		case result := <-wp.results:
			w.Header().Set("Content-Type", "application/json")
			json.NewEncoder(w).Encode(result)
		case <-ctx.Done():
			http.Error(w, "processing timeout", http.StatusGatewayTimeout)
		}
	}
}

func main() {
	registry := NewPatternRegistry()
	pool := NewWorkerPool(4, registry)

	mux := http.NewServeMux()
	mux.HandleFunc("/api/v1/jobs", makeJobHandler(pool))

	server := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 60 * time.Second,
	}

	log.Printf("Worker service starting on :8080")
	if err := server.ListenAndServe(); err != nil {
		log.Fatal(err)
	}
}
